<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Assessment;use Acorn\SafetyHealthcheck\Content\{ContentVersionRepository,QuestionRepository};final class SnapshotBuilder{public function build(int $id):array{$a=(new AssessmentRepository)->find($id);$answers=(new AnswerRepository)->all($id);$questions=(new QuestionRepository)->forVersion((int)$a['content_version_id']);$by=array_column($questions,null,'question_key');$items=[];foreach($answers as$x){$q=$by[$x['question_key']];$items[]=['question_key'=>$x['question_key'],'question_text'=>$q['question_text'],'module_key'=>$q['module_key'],'sort_rank'=>(int)$q['sort_order'],'answer'=>$x['answer_value'],'finding_status'=>$x['finding_status'],'positive_text'=>ucfirst(explode('_',strtolower($x['question_key']))[0]).' appears to be addressed based on your answer.','source'=>json_decode($q['source_json'],true)];}return['content_version_id'=>$a['content_version_id'],'profile'=>json_decode($a['profile_json'],true),'summary'=>['overall_status'=>$a['overall_status'],'priority_count'=>(int)$a['priority_count'],'review_count'=>(int)$a['review_count'],'addressed_count'=>(int)$a['addressed_count']],'findings'=>$items];}}
